package main

import "fmt"

// merge_sorted_lists deep merges two nested dictionaries (maps) recursively.
// Values from the second map override or merge into the first:
//   - If both values are maps, they are merged recursively.
//   - If both values are slices, the second is appended to the first.
//   - Otherwise the second value wins.
func merge_sorted_lists(a, b map[string]interface{}) map[string]interface{} {
	if a == nil {
		a = make(map[string]interface{})
	}
	result := make(map[string]interface{}, len(a))
	for k, v := range a {
		result[k] = v
	}
	for k, bv := range b {
		if av, ok := result[k]; ok {
			am, aIsMap := av.(map[string]interface{})
			bm, bIsMap := bv.(map[string]interface{})
			if aIsMap && bIsMap {
				result[k] = merge_sorted_lists(am, bm)
				continue
			}
			aSlice, aIsSlice := toSlice(av)
			bSlice, bIsSlice := toSlice(bv)
			if aIsSlice && bIsSlice {
				result[k] = append(aSlice, bSlice...)
				continue
			}
		}
		result[k] = bv
	}
	return result
}

// toSlice attempts to convert an interface{} to []interface{}.
func toSlice(v interface{}) ([]interface{}, bool) {
	switch s := v.(type) {
	case []interface{}:
		return s, true
	default:
		return nil, false
	}
}

// deepMergeMaps merges an arbitrary number of nested maps, left to right.
func deepMergeMaps(maps ...map[string]interface{}) map[string]interface{} {
	result := make(map[string]interface{})
	for _, m := range maps {
		result = merge_sorted_lists(result, m)
	}
	return result
}

// prettyPrint returns a string representation of a nested map for debugging.
func prettyPrint(m map[string]interface{}, indent int) string {
	s := "{\n"
	prefix := ""
	for i := 0; i <= indent; i++ {
		prefix += "  "
	}
	for k, v := range m {
		switch val := v.(type) {
		case map[string]interface{}:
			s += fmt.Sprintf("%s%q: %s\n", prefix, k, prettyPrint(val, indent+1))
		default:
			s += fmt.Sprintf("%s%q: %v\n", prefix, k, val)
		}
	}
	s += prefix[:len(prefix)-2] + "}"
	return s
}

